  primary ? primaryStyles : standardStyles,
  customStyles,
)!;

import { concatStyleSetsWithProps } from '@fluentui/react/lib/Styling';

const result = concatStyleSetsWithProps(
  { theme },
  p => ({ root: { color: p.theme.palette.themePrimary } }),
  { root: { padding: 8 } },
);

import { styled } from '@fluentui/react/lib/Utilities';
import { MyThingBase } from './MyThing.base';
import { getStyles } from './MyThing.styles';

export const MyThing = styled(
  MyThingBase,
  getStyles,
  undefined,
  { scope: 'MyThing' },
);

import { classNamesFunction } from '@fluentui/react/lib/Utilities';

const getClassNames = classNamesFunction<IMyStyleProps, IMyStyles>();

// in render (pass immutable scalars only):
const classNames = getClassNames(props.styles, {
  theme: props.theme!, className: props.className, disabled,
});
return <div className={classNames.root} />;

import { getFocusStyle } from '@fluentui/react/lib/Styling';

root: [
  getFocusStyle(theme, {
    inset: 2,
    borderRadius: theme.effects.roundedCorner2,
  }),
  { padding: 8 },
]

import { getGlobalClassNames } from '@fluentui/react/lib/Styling';

const GlobalClassNames = { root: 'ms-MyThing', label: 'ms-MyThing-label' };

export const getStyles = props => {
  const c = getGlobalClassNames(GlobalClassNames, props.theme);
  return { root: [c.root, { display: 'flex' }, props.className] };
};

