spfx.themingSnippet:
import { IReadonlyTheme } from '@microsoft/sp-component-base';

protected onThemeChanged(currentTheme: IReadonlyTheme | undefined): void {
  if (!currentTheme) { return; }
  this._isDarkTheme = !!currentTheme.isInverted;
  const { semanticColors } = currentTheme;
  if (semanticColors) {
    this.domElement.style.setProperty('--bodyText', semanticColors.bodyText || null);
    this.domElement.style.setProperty('--link', semanticColors.link || null);
    this.domElement.style.setProperty('--linkHovered', semanticColors.linkHovered || null);
  }
}
// SCSS: color: "[theme:bodyText, default: #323130]"; color: var(--bodyText);
// Section backgrounds: set manifest "supportsThemeVariants": true and consume
// ThemeProvider.serviceKey via this.context.serviceScope.consume(ThemeProvider.serviceKey)

teams.themingSnippet:
import { app } from '@microsoft/teams-js';
import { FluentProvider, teamsLightTheme, teamsDarkTheme, teamsHighContrastTheme } from '@fluentui/react-components';

const map = (t?: string) =>
  t === 'dark' ? teamsDarkTheme
  : t === 'contrast' ? teamsHighContrastTheme
  : teamsLightTheme; // 'default' and 'glass' fall back to light

await app.initialize();
const ctx = await app.getContext();
setTheme(map(ctx.app.theme));
app.registerOnThemeChangeHandler((t) => setTheme(map(t)));
