import { ThemeProvider } from '@fluentui/react';                       // v8
import { FluentProvider, PortalMountNodeProvider } from '@fluentui/react-components';
import { PortalCompatProvider } from '@fluentui/react-portal-compat';
import { createV8Theme } from '@fluentui/react-migration-v8-v9';

const v9Theme = webLightTheme;                    // or createLightTheme(createBrandVariants(v8Palette))
const v8Theme = createV8Theme(brandVariants, v9Theme, /*isDark*/ false);

root.render(
  <ThemeProvider theme={v8Theme}>              {/* v8 outer */}
    <FluentProvider theme={v9Theme}>           {/* v9 inner */}
      <PortalCompatProvider>                   {/* REQUIRED: inner child of FluentProvider */}
        <App />
      </PortalCompatProvider>
    </FluentProvider>
  </ThemeProvider>
);
